/**
 * The shape of the pinned SimulationCraft cooldown artifact, and a runtime
 * validator for it.
 *
 * Generated by `scripts/authority/extract-simc-cooldowns.mjs` from one exact
 * SimulationCraft commit and committed. Nothing here reaches the network.
 *
 * TWO EPISTEMIC GRADES IN ONE RECORD
 *
 * Each entry carries a machine-extracted DBC fact (`baseCooldownMs`, `charges`)
 * AND a hand-reviewed absence proof (`modifierPolicy`) asserting that nothing
 * modifies that cooldown. They are not the same kind of claim and the validator
 * refuses to let either masquerade as the other: `binding.method` must be
 * `MACHINE_EXTRACTED_DBC_RECORD` and `modifierPolicy.method` must be
 * `HAND_REVIEWED_CPP_ABSENCE_PROOF`, and neither string may appear in the other
 * slot.
 *
 * WHY THE ABSENCE PROOF IS THE FRAGILE ONE
 *
 * A DBC value that changes shows up as a different number in a hashed table. A
 * newly-added cooldown reset changes no DBC row at all — it is new C++ in a
 * 436 KB module. So the proof carries the SHA-256 of the module it was reviewed
 * against, and `checks` records the searches that were actually run rather than
 * only their conclusion. A reviewer can repeat them; a reader can see how wide
 * the claim is.
 *
 * WHAT A BASE COOLDOWN IS NOT
 *
 * Not haste-scaled, not reduced, not reset, not charge-aware beyond the recorded
 * charge count. Storing only the base fact means a decision needing more cannot
 * quietly get a plausible substitute.
 *
 * UNITS
 *
 * `_cooldown` is DBC MILLISECONDS; SimulationCraft expressions are in SECONDS.
 * The unit is part of every field name (`baseCooldownMs`) and the artifact
 * declares `cooldownFieldUnits`, which the validator pins. A milliseconds value
 * read as seconds turns a 60-second cooldown into 16 hours, which satisfies
 * every `remains<=` comparison in the pinned APL and never looks wrong.
 */

/** The artifact schema version this build understands. */
export const SUPPORTED_COOLDOWN_ARTIFACT_VERSION = 1;

/** The only unit string the artifact may claim. Validated, not merely documented. */
export const COOLDOWN_UNITS = "MILLISECONDS";

/** How a factual cooldown value was established. */
export const COOLDOWN_BINDING_METHOD = "MACHINE_EXTRACTED_DBC_RECORD";
/** How a "nothing modifies this" claim was established. Weaker, and labelled. */
export const MODIFIER_POLICY_METHOD = "HAND_REVIEWED_CPP_ABSENCE_PROOF";

/**
 * Where a cooldown begins.
 *
 * ONE member today. `ACTION_EXECUTE` is SimulationCraft's own anchor: the
 * cooldown starts inside `action_t::execute()`. An ability with a cast time or a
 * channel would need a different anchor, and giving that its own member later is
 * what stops this one from being stretched to cover it silently.
 */
export type CooldownStartAnchor = "ACTION_EXECUTE";

export interface CooldownArtifactSource {
  readonly path: string;
  readonly sha256: string;
  readonly byteLength: number;
}

export interface CooldownArtifactProvenance {
  readonly repository: string;
  readonly commitSha: string;
  readonly sources: readonly CooldownArtifactSource[];
  readonly clientDataWowVersion: string;
  readonly clientDataHotfixDate: string;
  readonly clientDataHotfixBuild: number;
  readonly clientDataHotfixHash: string;
  readonly cooldownFieldName: string;
  /** Always `MILLISECONDS`. */
  readonly cooldownFieldUnits: typeof COOLDOWN_UNITS;
  readonly extractedOn: string;
  readonly extractorVersion: number;
  readonly applicabilityNote: string;
}

export interface CooldownBinding {
  readonly method: typeof COOLDOWN_BINDING_METHOD;
  readonly sourcePath: string;
  readonly createAction: string;
  readonly specBinding: string;
}

/** One search a human performed, and what it found. */
export interface ModifierPolicyCheck {
  readonly claim: string;
  readonly search: string;
  readonly finding: string;
}

/**
 * The hand-reviewed claim that nothing modifies this cooldown.
 *
 * `sourceSha256` is the whole point. A pinned-source change that adds a reset
 * invalidates this claim without touching any DBC value, so the hash is the only
 * thing that can catch it.
 */
export interface CooldownModifierPolicy {
  readonly method: typeof MODIFIER_POLICY_METHOD;
  /** The token this claim is about. NEVER a claim about any other ability. */
  readonly appliesTo: string;
  readonly sourcePath: string;
  readonly sourceSha256: string;
  readonly reviewedOn: string;
  readonly checks: readonly ModifierPolicyCheck[];
}

export interface CooldownStartContract {
  readonly anchor: CooldownStartAnchor;
  readonly evidence: readonly string[];
  readonly note: string;
}

export interface CooldownIdentity {
  /** The token as it appears after `cooldown.` in a SimulationCraft expression. */
  readonly simcToken: string;
  /** The spell id. What a Warcraft Logs cast event carries as `abilityGameID`. */
  readonly abilityGameId: number;
  /** Human-readable only. Never used for matching. */
  readonly displayNameEn: string;
  /** `spell_data_t::_cooldown`, in MILLISECONDS. Base only. */
  readonly baseCooldownMs: number;
  /** `_charges`. Zero means no charge system, which is what the policy assumes. */
  readonly charges: number;
  readonly chargeCooldownMs: number;
  readonly categoryCooldownMs: number;
  readonly baseGcdMs: number;
  readonly classId: number;
  readonly specId: number;
  readonly binding: CooldownBinding;
  readonly modifierPolicy: CooldownModifierPolicy;
  readonly cooldownStart: CooldownStartContract;
}

export interface CooldownArtifact {
  readonly artifactVersion: number;
  readonly datasetId: string;
  readonly artifactRevision: string;
  readonly provenance: CooldownArtifactProvenance;
  readonly cooldowns: readonly CooldownIdentity[];
}

/**
 * Field names that must NOT appear on a cooldown entry.
 *
 * Each depends on a fight moment or an actor. Baking one in would turn a
 * per-decision derivation into a constant nobody re-checks.
 */
export const FORBIDDEN_DERIVED_COOLDOWN_KEYS = [
  "remains",
  "remainsSeconds",
  "remainsMs",
  "ready",
  "baseCooldownSeconds",
  "hastedCooldownMs",
] as const;

export type CooldownArtifactValidationReason =
  | "NOT_AN_OBJECT"
  | "UNSUPPORTED_ARTIFACT_VERSION"
  | "MALFORMED_PROVENANCE"
  | "UNSUPPORTED_COOLDOWN_UNITS"
  | "MALFORMED_COOLDOWNS"
  | "MALFORMED_COOLDOWN"
  | "MALFORMED_BINDING"
  | "MALFORMED_MODIFIER_POLICY"
  | "CONFLATED_PROVENANCE_GRADES"
  | "DUPLICATE_TOKEN"
  | "DUPLICATE_ABILITY_ID";

export type CooldownArtifactValidation =
  | { readonly ok: true; readonly artifact: CooldownArtifact }
  | { readonly ok: false; readonly reason: CooldownArtifactValidationReason; readonly detail: string };

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function str(record: Record<string, unknown>, key: string): string | null {
  const value = record[key];
  return typeof value === "string" && value.length > 0 ? value : null;
}

function positiveInt(record: Record<string, unknown>, key: string): number | null {
  const value = record[key];
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0 ? value : null;
}

function nonNegativeInt(record: Record<string, unknown>, key: string): number | null {
  const value = record[key];
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0 ? value : null;
}

function invalid(reason: CooldownArtifactValidationReason, detail: string): CooldownArtifactValidation {
  return { ok: false, reason, detail };
}

function validateSources(value: unknown): readonly CooldownArtifactSource[] | null {
  if (!Array.isArray(value) || value.length === 0) return null;
  const sources: CooldownArtifactSource[] = [];
  for (const raw of value) {
    if (!isRecord(raw)) return null;
    const path = str(raw, "path");
    const sha256 = str(raw, "sha256");
    const byteLength = positiveInt(raw, "byteLength");
    if (path === null || sha256 === null || byteLength === null) return null;
    if (!/^[0-9a-f]{64}$/.test(sha256)) return null;
    sources.push({ path, sha256, byteLength });
  }
  return sources;
}

function validateProvenance(value: unknown): CooldownArtifactProvenance | "BAD_UNITS" | null {
  if (!isRecord(value)) return null;
  const repository = str(value, "repository");
  const commitSha = str(value, "commitSha");
  const clientDataWowVersion = str(value, "clientDataWowVersion");
  const clientDataHotfixDate = str(value, "clientDataHotfixDate");
  const clientDataHotfixHash = str(value, "clientDataHotfixHash");
  const cooldownFieldName = str(value, "cooldownFieldName");
  const extractedOn = str(value, "extractedOn");
  const applicabilityNote = str(value, "applicabilityNote");
  const clientDataHotfixBuild = positiveInt(value, "clientDataHotfixBuild");
  const extractorVersion = positiveInt(value, "extractorVersion");
  const sources = validateSources(value["sources"]);

  if (
    repository === null ||
    commitSha === null ||
    clientDataWowVersion === null ||
    clientDataHotfixDate === null ||
    clientDataHotfixHash === null ||
    cooldownFieldName === null ||
    extractedOn === null ||
    applicabilityNote === null ||
    clientDataHotfixBuild === null ||
    extractorVersion === null ||
    sources === null
  ) {
    return null;
  }
  if (!/^[0-9a-f]{40}$/.test(commitSha)) return null;
  if (value["cooldownFieldUnits"] !== COOLDOWN_UNITS) return "BAD_UNITS";

  return {
    repository,
    commitSha,
    sources,
    clientDataWowVersion,
    clientDataHotfixDate,
    clientDataHotfixBuild,
    clientDataHotfixHash,
    cooldownFieldName,
    cooldownFieldUnits: COOLDOWN_UNITS,
    extractedOn,
    extractorVersion,
    applicabilityNote,
  };
}

function validateBinding(value: unknown): CooldownBinding | null {
  if (!isRecord(value)) return null;
  const sourcePath = str(value, "sourcePath");
  const createAction = str(value, "createAction");
  const specBinding = str(value, "specBinding");
  if (
    value["method"] !== COOLDOWN_BINDING_METHOD ||
    sourcePath === null ||
    createAction === null ||
    specBinding === null
  ) {
    return null;
  }
  return { method: COOLDOWN_BINDING_METHOD, sourcePath, createAction, specBinding };
}

function validateModifierPolicy(value: unknown, simcToken: string): CooldownModifierPolicy | null {
  if (!isRecord(value)) return null;
  const appliesTo = str(value, "appliesTo");
  const sourcePath = str(value, "sourcePath");
  const sourceSha256 = str(value, "sourceSha256");
  const reviewedOn = str(value, "reviewedOn");
  if (
    value["method"] !== MODIFIER_POLICY_METHOD ||
    appliesTo === null ||
    sourcePath === null ||
    sourceSha256 === null ||
    reviewedOn === null
  ) {
    return null;
  }
  if (!/^[0-9a-f]{64}$/.test(sourceSha256)) return null;
  // A policy reviewed for a DIFFERENT ability is not a policy for this one.
  if (appliesTo !== simcToken) return null;

  const rawChecks = value["checks"];
  if (!Array.isArray(rawChecks) || rawChecks.length === 0) return null;
  const checks: ModifierPolicyCheck[] = [];
  for (const raw of rawChecks) {
    if (!isRecord(raw)) return null;
    const claim = str(raw, "claim");
    const search = str(raw, "search");
    const finding = str(raw, "finding");
    if (claim === null || search === null || finding === null) return null;
    checks.push({ claim, search, finding });
  }

  return { method: MODIFIER_POLICY_METHOD, appliesTo, sourcePath, sourceSha256, reviewedOn, checks };
}

function validateStartContract(value: unknown): CooldownStartContract | null {
  if (!isRecord(value)) return null;
  const note = str(value, "note");
  if (value["anchor"] !== "ACTION_EXECUTE" || note === null) return null;
  const rawEvidence = value["evidence"];
  if (!Array.isArray(rawEvidence) || rawEvidence.length === 0) return null;
  const evidence: string[] = [];
  for (const entry of rawEvidence) {
    if (typeof entry !== "string" || entry.length === 0) return null;
    evidence.push(entry);
  }
  return { anchor: "ACTION_EXECUTE", evidence, note };
}

export function validateCooldownArtifact(value: unknown): CooldownArtifactValidation {
  if (!isRecord(value)) return invalid("NOT_AN_OBJECT", "artifact root is not an object");

  const artifactVersion = value["artifactVersion"];
  if (artifactVersion !== SUPPORTED_COOLDOWN_ARTIFACT_VERSION) {
    return invalid(
      "UNSUPPORTED_ARTIFACT_VERSION",
      `artifactVersion ${String(artifactVersion)} is not ${SUPPORTED_COOLDOWN_ARTIFACT_VERSION}`,
    );
  }

  const datasetId = str(value, "datasetId");
  const artifactRevision = str(value, "artifactRevision");
  if (datasetId === null || artifactRevision === null) {
    return invalid("NOT_AN_OBJECT", "artifact header fields are missing or malformed");
  }

  const provenance = validateProvenance(value["provenance"]);
  if (provenance === "BAD_UNITS") {
    return invalid(
      "UNSUPPORTED_COOLDOWN_UNITS",
      `provenance.cooldownFieldUnits must be '${COOLDOWN_UNITS}'; a cooldown whose unit is unconfirmed cannot be converted`,
    );
  }
  if (provenance === null) {
    return invalid("MALFORMED_PROVENANCE", "provenance is incomplete or a hash is not a hash");
  }

  const raws = value["cooldowns"];
  if (!Array.isArray(raws) || raws.length === 0) {
    return invalid("MALFORMED_COOLDOWNS", "cooldowns is not a non-empty array");
  }

  const cooldowns: CooldownIdentity[] = [];
  const seenTokens = new Set<string>();
  const seenIds = new Set<number>();

  for (let index = 0; index < raws.length; index += 1) {
    const raw = raws[index];
    if (!isRecord(raw)) return invalid("MALFORMED_COOLDOWN", `cooldowns[${index}] is not an object`);
    for (const forbidden of FORBIDDEN_DERIVED_COOLDOWN_KEYS) {
      if (forbidden in raw) {
        return invalid(
          "MALFORMED_COOLDOWN",
          `cooldowns[${index}] stores '${forbidden}'; that is derived per decision, never baked into the dataset`,
        );
      }
    }

    const simcToken = str(raw, "simcToken");
    const nameEn = str(raw, "displayNameEn");
    const abilityGameId = positiveInt(raw, "abilityGameId");
    const baseCooldownMs = positiveInt(raw, "baseCooldownMs");
    const charges = nonNegativeInt(raw, "charges");
    const chargeCooldownMs = nonNegativeInt(raw, "chargeCooldownMs");
    const categoryCooldownMs = nonNegativeInt(raw, "categoryCooldownMs");
    const baseGcdMs = nonNegativeInt(raw, "baseGcdMs");
    const classId = positiveInt(raw, "classId");
    const specId = positiveInt(raw, "specId");

    if (
      simcToken === null ||
      nameEn === null ||
      abilityGameId === null ||
      baseCooldownMs === null ||
      charges === null ||
      chargeCooldownMs === null ||
      categoryCooldownMs === null ||
      baseGcdMs === null ||
      classId === null ||
      specId === null
    ) {
      return invalid(
        "MALFORMED_COOLDOWN",
        `cooldowns[${index}] is missing required fields or has a non-positive base cooldown`,
      );
    }

    const binding = validateBinding(raw["binding"]);
    if (binding === null) {
      return invalid("MALFORMED_BINDING", `cooldowns[${index}] has an unusable binding record`);
    }
    const modifierPolicy = validateModifierPolicy(raw["modifierPolicy"], simcToken);
    if (modifierPolicy === null) {
      return invalid(
        "MALFORMED_MODIFIER_POLICY",
        `cooldowns[${index}] has an unusable modifier policy, or one reviewed for a different ability`,
      );
    }
    // Neither grade may wear the other's label. A machine-extraction claim on an
    // absence proof would present a human's reading as reproducible parsing.
    if (
      String(binding.method) === String(MODIFIER_POLICY_METHOD) ||
      String(modifierPolicy.method) === String(COOLDOWN_BINDING_METHOD)
    ) {
      return invalid(
        "CONFLATED_PROVENANCE_GRADES",
        `cooldowns[${index}] labels a hand-reviewed claim as machine extraction or vice versa`,
      );
    }

    const cooldownStart = validateStartContract(raw["cooldownStart"]);
    if (cooldownStart === null) {
      return invalid("MALFORMED_COOLDOWN", `cooldowns[${index}] has no usable cooldown-start contract`);
    }

    if (seenTokens.has(simcToken)) return invalid("DUPLICATE_TOKEN", simcToken);
    if (seenIds.has(abilityGameId)) return invalid("DUPLICATE_ABILITY_ID", String(abilityGameId));
    seenTokens.add(simcToken);
    seenIds.add(abilityGameId);

    cooldowns.push({
      simcToken,
      abilityGameId,
      displayNameEn: nameEn,
      baseCooldownMs,
      charges,
      chargeCooldownMs,
      categoryCooldownMs,
      baseGcdMs,
      classId,
      specId,
      binding,
      modifierPolicy,
      cooldownStart,
    });
  }

  return { ok: true, artifact: { artifactVersion, datasetId, artifactRevision, provenance, cooldowns } };
}
